// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address newOwner, uint256 amount) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));
        amount = bound(amount, 1, type(uint256).max / 2);

        // owner at deploy time is address(this); move ownership to a fuzzed EOA
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // fund the contract with a fuzzed amount of ether
        vm.deal(address(c), amount);

        // owner withdraws
        vm.prank(newOwner);
        c.withdraw();

        // General rule: after withdraw(), the contract retains NO ether.
        assertTrue(address(c).balance == 0);
    }
}
